'use strict';

// MODULES //

var tape = require( 'tape' );
var isObject = require( '@stdlib/assert/is-object' );
var ctor = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof ctor, 'function', 'main export is a function' );
	t.end();
});

tape( 'an instance has a `toJSON` method', function test( t ) {
	var chart = ctor();
	t.strictEqual( typeof chart.toJSON, 'function', 'returns expected value' );
	t.end();
});

tape( 'the method serializes a chart as a JSON object', function test( t ) {
	var chart;
	var json;

	chart = ctor();
	json = chart.toJSON();

	t.strictEqual( isObject( json ), true, 'returns an object' );
	t.strictEqual( json.marks.length, 0, 'returns expected value' );
	t.strictEqual( json.legends.length, 0, 'returns expected value' );

	t.end();
});

tape( 'the method generates one line mark per dataset', function test( t ) {
	var chart;
	var json;

	chart = ctor( [ 1, 2, 3 ], [ 4, 5, 6 ] );
	json = chart.toJSON();
	t.strictEqual( json.marks.length, 1, 'returns expected value' );
	t.strictEqual( json.marks[ 0 ].type, 'line', 'returns expected value' );
	t.strictEqual( json.marks[ 0 ].from.data, json.data[ 0 ].name, 'returns expected value' );

	chart = ctor( [ 1, 2, 3 ], [ [ 4, 5, 6 ], [ 7, 8, 9 ] ] );
	json = chart.toJSON();
	t.strictEqual( json.marks.length, 2, 'returns expected value' );
	t.strictEqual( json.marks[ 0 ].from.data, json.data[ 0 ].name, 'returns expected value' );
	t.strictEqual( json.marks[ 1 ].from.data, json.data[ 1 ].name, 'returns expected value' );

	t.end();
});

tape( 'the method reuses existing marks across serializations', function test( t ) {
	var chart;
	var m1;
	var m2;

	chart = ctor( [ 1, 2, 3 ], [ 4, 5, 6 ] );

	m1 = chart.toJSON().marks;
	m2 = chart.toJSON().marks;

	t.strictEqual( m1.length, 1, 'returns expected value' );
	t.strictEqual( m2.length, 1, 'returns expected value' );
	t.strictEqual( chart.config.marks[ 0 ], chart.config.marks[ 0 ], 'reuses mark instance' );

	t.end();
});

tape( 'the method prunes marks when the number of datasets decreases', function test( t ) {
	var chart;
	var json;

	chart = ctor( [ 1, 2, 3 ], [ [ 4, 5, 6 ], [ 7, 8, 9 ] ] );
	json = chart.toJSON();
	t.strictEqual( json.marks.length, 2, 'returns expected value' );

	chart.data = [ [ 1, 2, 3 ], [ 4, 5, 6 ] ];
	json = chart.toJSON();
	t.strictEqual( json.marks.length, 1, 'returns expected value' );

	t.end();
});

tape( 'the method updates the internal encoding scales', function test( t ) {
	var chart;
	var json;
	var i;

	chart = ctor( [ 1, 2, 3 ], [ [ 4, 5, 6 ], [ 7, 8, 9 ] ], {
		'colors': [ 'red', 'blue' ],
		'lineOpacity': [ 1.0, 0.5 ],
		'lineSymbol': [ 'stroke', 'circle' ],
		'lineWidth': [ 2, 4 ]
	});
	json = chart.toJSON();

	t.deepEqual( chart.colorScale.domain, [ json.data[ 0 ].name, json.data[ 1 ].name ], 'returns expected value' );
	t.deepEqual( chart.colorScale.range, [ 'red', 'blue' ], 'returns expected value' );
	t.deepEqual( chart.lineOpacityScale.range, [ 1.0, 0.5 ], 'returns expected value' );
	t.deepEqual( chart.lineSymbolScale.range, [ 'stroke', 'circle' ], 'returns expected value' );
	t.deepEqual( chart.lineWidthScale.range, [ 2, 4 ], 'returns expected value' );

	for ( i = 0; i < json.marks.length; i++ ) {
		t.strictEqual( json.marks[ i ].encode.update.stroke.scale, 'colorScale', 'returns expected value' );
		t.strictEqual( json.marks[ i ].encode.update.stroke.value, json.data[ i ].name, 'returns expected value' );
		t.strictEqual( json.marks[ i ].encode.update.strokeWidth.scale, 'lineWidthScale', 'returns expected value' );
		t.strictEqual( json.marks[ i ].encode.update.strokeWidth.value, json.data[ i ].name, 'returns expected value' );
	}
	t.end();
});

tape( 'the method is implicitly invoked by `JSON.stringify`', function test( t ) {
	var chart;
	var json;

	chart = ctor( [ 1, 2, 3 ], [ 4, 5, 6 ] );
	json = JSON.parse( JSON.stringify( chart ) );

	t.strictEqual( isObject( json ), true, 'returns an object' );
	t.strictEqual( json.marks.length, 1, 'returns expected value' );

	t.end();
});
